    for dr in (-2,0,2,3,5,7,10):
        for dc in (-2,0,2,3,5,7,10):
            if dr or dc:
                x,y=obj['r0']+dr,obj['c0']+dc
                if 0<=x<H and 0<=y<W and g[x][y]!=bg and (x,y) not in obj['cells']:
                    cnt[g[x][y]]+=1
    return dict(cnt)
